class Solution {
  public int earliestFinishTime(
      int[] landStartTime, int[] landDuration, int[] waterStartTime, int[] waterDuration) {
    return Math.min(
        finish(landStartTime, landDuration, waterStartTime, waterDuration),
        finish(waterStartTime, waterDuration, landStartTime, landDuration));
  }

  // earliest finish when the first ride comes from (s1, d1) and the second from (s2, d2)
  private int finish(int[] s1, int[] d1, int[] s2, int[] d2) {
    int firstDone = Integer.MAX_VALUE;
    for (int i = 0; i < s1.length; i++) firstDone = Math.min(firstDone, s1[i] + d1[i]);
    int best = Integer.MAX_VALUE;
    for (int j = 0; j < s2.length; j++) best = Math.min(best, Math.max(firstDone, s2[j]) + d2[j]);
    return best;
  }
}
